require_once __DIR__.'/includes/module.php'; require_roles(['admin','admin_hrd']);$page_title='Data Personel HRD';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');if($name){$q=$pdo->prepare('INSERT INTO hrd_personnel(employee_code,name,position_title,department,phone,email,employment_status,join_date,notes) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([trim($_POST['employee_code']??'')?:null,$name,trim($_POST['position_title']??'')?:null,trim($_POST['department']??'')?:null,trim($_POST['phone']??'')?:null,trim($_POST['email']??'')?:null,$_POST['employment_status']??'Aktif',($_POST['join_date']??'')?:null,trim($_POST['notes']??'')?:null]);flash('Data personel berhasil ditambahkan.');}else flash('Nama personel wajib diisi.');header('Location: hrd.php');exit;}
$rows=$pdo->query('SELECT * FROM hrd_personnel ORDER BY name')->fetchAll();require __DIR__.'/includes/header.php';show_flash();
?>
<section class="panel"><div class="panel-head"><h3>Tambah Personel</h3></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Nomor/kode personel</label><input name="employee_code"></div><div class="field"><label>Nama lengkap *</label><input name="name" required></div><div class="field"><label>Jabatan</label><input name="position_title"></div><div class="field"><label>Divisi</label><input name="department"></div><div class="field"><label>No. HP</label><input name="phone"></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field"><label>Status</label><select name="employment_status"><option>Aktif</option><option>Cuti</option><option>Tidak Aktif</option></select></div><div class="field"><label>Tanggal bergabung</label><input type="date" name="join_date"></div><div class="field full"><label>Catatan</label><textarea name="notes" rows="2"></textarea></div></div><div class="form-actions"><button class="btn">Simpan Personel</button></div></form></section>
<section class="panel"><div class="panel-head"><h3>Daftar Personel</h3></div><table><thead><tr><th>Kode</th><th>Nama</th><th>Jabatan</th><th>Divisi</th><th>Kontak</th><th>Status</th><th>Dokumen</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">Belum ada data personel.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['employee_code']?:'-')?></td><td><?=e($r['name'])?></td><td><?=e($r['position_title']?:'-')?></td><td><?=e($r['department']?:'-')?></td><td><?=e($r['phone']?:$r['email']?:'-')?></td><td><?=e($r['employment_status'])?></td><td><a href="hrd_documents.php?personnel_id=<?=$r['id']?>">Kelola dokumen</a></td></tr><?php endforeach;endif;?></tbody></table></section>
